import { NextRequest, NextResponse } from 'next/server'
import { prisma } from '@/lib/prisma'
import { headers } from 'next/headers'

// 获取用户标识符（简单实现，基于IP）
async function getUserIdentifier(request: NextRequest): Promise<string> {
  const headersList = await headers()
  const xRealIp = headersList.get('x-real-ip')
  const xForwardedFor = headersList.get('x-forwarded-for')
  const ip = xRealIp || xForwardedFor?.split(',')[0] || 'unknown'
  return `ip_${ip}`
}

// GET - 获取用户的音乐卡片记录
export async function GET(request: NextRequest) {
  try {
    const userIdentifier = await getUserIdentifier(request)
    const url = new URL(request.url)
    const page = parseInt(url.searchParams.get('page') || '1')
    const limit = parseInt(url.searchParams.get('limit') || '20')
    const skip = (page - 1) * limit

    const musicCards = await prisma.musicCard.findMany({
      where: {
        userIdentifier
      },
      orderBy: {
        createdAt: 'desc'
      },
      skip,
      take: limit
    })

    const total = await prisma.musicCard.count({
      where: { userIdentifier }
    })

    return NextResponse.json({
      success: true,
      data: {
        musicCards,
        pagination: {
          page,
          limit,
          total,
          totalPages: Math.ceil(total / limit)
        }
      }
    })
  } catch (error) {
    console.error('获取音乐卡片记录失败:', error)
    return NextResponse.json(
      { success: false, error: '获取记录失败' },
      { status: 500 }
    )
  }
}

// POST - 创建新的音乐卡片记录
export async function POST(request: NextRequest) {
  try {
    const userIdentifier = await getUserIdentifier(request)
    const body = await request.json()

    const {
      title,
      artist,
      coverUrl,
      lyrics,
      duration,
      playDuration,
      originalUrl,
      platform,
      template,
      config,
      displayTitle
    } = body

    // 验证必需字段
    if (!title || !artist || !coverUrl || !originalUrl || !platform || !template) {
      return NextResponse.json(
        { success: false, error: '缺少必需字段' },
        { status: 400 }
      )
    }

    const musicCard = await prisma.musicCard.create({
      data: {
        title,
        artist,
        coverUrl,
        lyrics: lyrics || null,
        duration: duration || 0,
        playDuration: playDuration || null,
        originalUrl,
        platform,
        template,
        config: config ? JSON.stringify(config) : null,
        displayTitle: displayTitle || title,
        userIdentifier
      }
    })

    return NextResponse.json({
      success: true,
      data: musicCard
    })
  } catch (error) {
    console.error('创建音乐卡片记录失败:', error)
    return NextResponse.json(
      { success: false, error: '创建记录失败' },
      { status: 500 }
    )
  }
} 